const nums = [5, 2, 8, 1];
nums.push(10);
console.log(nums.length, nums[0], nums[nums.length - 1]);
console.log(nums.includes(8), nums.indexOf(8));
console.log(nums.slice(1, 3));

const prices = [10, 25, 7, 40];
const doubled = prices.map((p) => p * 2);
const cheap = prices.filter((p) => p < 20);
const total = prices.reduce((sum, p) => sum + p, 0);
console.log(doubled);
console.log(cheap);
console.log(total);

const names = ["Яна", "Борис", "Анна"];
console.log(names.find((n) => n.startsWith("Б")));
console.log(names.some((n) => n.length > 4), names.every((n) => n.length > 4));
console.log([...names].sort());

const a = [10, 9, 100, 1];
console.log([...a].sort());
console.log([...a].sort((x, y) => x - y));
